"""Generate the protocol 3.4 test vectors in tinytuya34.json with tinytuya 1.20.0.

Fake key and nonces only. Run it in a throwaway container:

    docker run --rm -v "$PWD":/vec:ro python:3.13-slim \\
        sh -c "pip install -q tinytuya==1.20.0 && python -I /vec/gen_tinytuya34.py" > tinytuya34.json
"""
import hmac, json
from hashlib import sha256
import tinytuya
from tinytuya.core import message_helper as M, header as H, crypto_helper as C
from tinytuya.core.message_helper import TuyaMessage, MessagePayload

KEY = b"fake-local-key!!"            # 16 bytes, not a real key
LOCAL_NONCE = bytes(range(0x10, 0x20))
REMOTE_NONCE = bytes(range(0xA0, 0xB0))
DEV = "fakedevice0000000000"

out = {"local_key": KEY.decode(), "local_nonce": LOCAL_NONCE.hex(), "remote_nonce": REMOTE_NONCE.hex()}

d = tinytuya.Device(DEV, address="192.0.2.10", local_key=KEY.decode(), version=3.4)
d.seqno = 1
step1 = d._negotiate_session_key_generate_step_1()
d.local_nonce = LOCAL_NONCE        # pin the nonce generated by step 1
step1 = MessagePayload(step1.cmd, LOCAL_NONCE)
out["neg_start"] = d._encode_message(step1).hex()

# What the device answers: retcode 0, then ECB(realKey, remoteNonce + HMAC(realKey, localNonce)).
inner = REMOTE_NONCE + hmac.new(KEY, LOCAL_NONCE, sha256).digest()
enc = C.AESCipher(KEY).encrypt(inner, False)
resp = M.pack_message(TuyaMessage(7, 4, None, b"\x00\x00\x00\x00" + enc, 0, True, H.PREFIX_55AA_VALUE, None), hmac_key=KEY)
out["neg_resp"] = resp.hex()

rkey = M.unpack_message(resp, hmac_key=KEY)
assert rkey.crc_good and rkey.retcode == 0
step3 = d._negotiate_session_key_generate_step_3(rkey)
assert step3
out["neg_finish"] = d._encode_message(step3).hex()
d._negotiate_session_key_generate_finalize()
session = d.local_key
out["session_key"] = session.hex()

# Heartbeat (cmd 9) under the session key: no version header (NO_PROTOCOL_HEADER_CMDS).
out["heartbeat_seq"] = d.seqno
out["heartbeat"] = d._encode_message(MessagePayload(9, b"")).hex()

# A control command (cmd 7) keeps tinytuya's version header: "3.4" + 12 zero bytes.
ctrl = json.dumps({"dps": {"1": True}}, separators=(",", ":")).encode()
out["control_body"] = ctrl.decode()
out["control_seq"] = d.seqno
out["control"] = d._encode_message(MessagePayload(7, ctrl)).hex()

# Command 32 the way the camera accepts it: same framing, NO version header.
sig = json.dumps({"header": {"type": "offer", "path": "lan"}, "msg": {"sdp": "v=0"}}, separators=(",", ":")).encode()
out["signal_body"] = sig.decode()
out["signal_seq"] = d.seqno
encsig = C.AESCipher(session).encrypt(sig, False)
out["signal"] = M.pack_message(TuyaMessage(d.seqno, 32, 0, encsig, 0, True, H.PREFIX_55AA_VALUE, False), hmac_key=session).hex()
d.seqno += 1
# And tinytuya's own encoding, which prepends the header the camera ignores.
out["signal_with_header"] = d._encode_message(MessagePayload(32, sig)).hex()

# A frame from the camera: retcode 0 then the ciphertext, HMAC over both.
ans = json.dumps({"header": {"type": "answer", "path": "lan"}, "msg": {"sdp": "a=ice-ufrag:abcd"}}, separators=(",", ":")).encode()
out["answer_body"] = ans.decode()
encans = C.AESCipher(session).encrypt(ans, False)
ansframe = M.pack_message(TuyaMessage(42, 32, None, b"\x00\x00\x00\x00" + encans, 0, True, H.PREFIX_55AA_VALUE, None), hmac_key=session)
chk = M.unpack_message(ansframe, hmac_key=session)
assert chk.crc_good
assert d._decode_payload(chk.payload)["header"]["type"] == "answer"
out["answer"] = ansframe.hex()

print(json.dumps(out, indent=1))
